import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './OrderPage.scss';

interface City {
    Ref: string;
    Description: string;
}

interface Warehouse {
    Ref: string;
    Description: string;
}

interface ApiResponse<T> {
    success: boolean;
    data: T;
    errors: any[];
    warnings: any[];
}

const OrderPage = () => {
    const [cities, setCities] = useState<City[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [selectedCity, setSelectedCity] = useState('');
    const [selectedWarehouse, setSelectedWarehouse] = useState('');
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        address: '',
        phone: '',
    });

    const API_KEY = '4b43b81dfa23afae2dbf44851510a110'; // Вставте свій API-ключ

    // Завантаження списку міст
    useEffect(() => {
        axios
            .post('https://api.novaposhta.ua/v2.0/json/', {
                apiKey: API_KEY,
                modelName: 'Address',
                calledMethod: 'getCities',
                methodProperties: {},
            })
            .then((response) => {
                const citiesData = (response.data as ApiResponse<City[]>).data; // Явна типізація відповіді
                setCities(citiesData);
            })
            .catch((error) => {
                console.error('Error fetching cities:', error);
            });
    }, []);

    // Завантаження відділень для обраного міста
    useEffect(() => {
        if (selectedCity) {
            axios
                .post('https://api.novaposhta.ua/v2.0/json/', {
                    apiKey: API_KEY,
                    modelName: 'Address',
                    calledMethod: 'getWarehouses',
                    methodProperties: {
                        CityRef: selectedCity,
                    },
                })
                .then((response) => {
                    const warehousesData = (response.data as ApiResponse<Warehouse[]>).data; // Явна типізація відповіді
                    setWarehouses(warehousesData);
                })
                .catch((error) => {
                    console.error('Error fetching warehouses:', error);
                });
        }
    }, [selectedCity]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
    };

    const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        console.log('Form Data:', { ...formData, selectedCity, selectedWarehouse });
        // Логіка для обробки замовлення
    };

    return (
        <div className="order-page">
            <h1>Order Form</h1>
            <form onSubmit={handleSubmit}>
                <div className="form-group">
                    <label htmlFor="name">Name</label>
                    <input
                        id="name"
                        name="name"
                        type="text"
                        value={formData.name}
                        onChange={handleInputChange}
                    />
                </div>
                <div className="form-group">
                    <label htmlFor="email">Email</label>
                    <input
                        id="email"
                        name="email"
                        type="email"
                        value={formData.email}
                        onChange={handleInputChange}
                    />
                </div>
                <div className="form-group">
                    <label htmlFor="phone">Phone</label>
                    <input
                        id="phone"
                        name="phone"
                        type="text"
                        value={formData.phone}
                        onChange={handleInputChange}
                    />
                </div>

                {/* Вибір міста */}
                <div className="form-group">
                    <label htmlFor="city">Доставка Нова Пошт</label>
                    <select
                        id="city"
                        value={selectedCity}
                        onChange={(e) => setSelectedCity(e.target.value)}
                    >
                        <option value="">Select your city</option>
                        {cities.map((city) => (
                            <option key={city.Ref} value={city.Ref}>
                                {city.Description}
                            </option>
                        ))}
                    </select>
                </div>

                {/* Вибір відділення */}
                <div className="form-group">
                    <label htmlFor="warehouse">Warehouse</label>
                    <select
                        id="warehouse"
                        value={selectedWarehouse}
                        onChange={(e) => setSelectedWarehouse(e.target.value)}
                        disabled={!selectedCity}
                    >
                        <option value="">Select your warehouse</option>
                        {warehouses.map((warehouse) => (
                            <option key={warehouse.Ref} value={warehouse.Ref}>
                                {warehouse.Description}
                            </option>
                        ))}
                    </select>
                </div>

                <button type="submit">Submit Order</button>
            </form>
        </div>
    );
};

export default OrderPage;
